def paintersPartition(boards: list[int], k: int) -> int:
    def countPainters(maxTime):
        painters = 1
        currentSum = 0
        for b in boards:
            if currentSum + b <= maxTime:
                currentSum += b
            else:
                painters += 1
                currentSum = b
        return painters

    low = max(boards)
    high = sum(boards)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if countPainters(mid) <= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

